"""CloudFormation Template Generator for AgentCore Flows.

Converts a DeployRequest (workflow definition from the frontend) into a
complete CloudFormation template bundle using native AWS::BedrockAgentCore::*
resource types wherever they exist.

Four Custom Resources are emitted, all served by the single cfn-provider
Lambda in ``cfn_provider/handler.py``, because no native CFN type covers them:

- ``Custom::AgentCodePackage`` — merges the agent code with a prebuilt
  dependency bundle and uploads the final code.zip at deploy time. Always
  present.
- ``Custom::RuntimeLogGroup`` — applies the stack's retention period and
  customer-managed key to the log groups AgentCore creates for each runtime.
  ``AWS::BedrockAgentCore::Runtime`` has no logging properties, and the service
  creates the groups itself, so nothing declared can reach them. One per
  runtime, always present.
- ``Custom::OAuth2CredentialProvider`` — creates the AgentCore OAuth2
  credential provider that authenticates the Gateway to an MCP Server
  Runtime. Emitted only on the MCP-server path.
- ``Custom::AgentCorePolicy`` — creates the Cedar policy attached to a
  PolicyEngine. Emitted only when a policy is configured.

Keep this list in sync with the handler dispatch in
``cfn_provider/handler.py`` and with the architecture note in the generated
README (``_generate_readme``). All three have drifted before.

The generated bundle includes:
- template.yaml — CloudFormation template
- agent-code/agent.py — Pre-generated agent code (env-var driven)
- cfn-provider/ — Custom Resource Lambda (code packaging, runtime log group
  governance, OAuth2 credential provider, Cedar policy)
- tool-lambdas/ — Gateway tool Lambda functions (if applicable)
- deploy.sh — One-command deployment script
- teardown.sh — Stack deletion script
- README.md — Documentation

Note that the bundle is NOT self-contained: the template also requires a
prebuilt dependency bundle to already exist in the target S3 bucket under the
``DependencyBundleKey`` parameter. See the README section generated by
``_generate_readme``.
"""

import hashlib
import io
import logging
import os
import re
import zipfile
from collections.abc import Callable
from dataclasses import dataclass

import yaml

from app.models.deployment_models import DeployRequest, RuntimeConfig
from app.services import codegen_templates
from app.services.code_generator import generate_agent_code, resolve_model_id
from app.services.litellm_gateway_deployer import resolve_gateway_provider, resolve_mcp_url
from app.services.observability import build_otel_env_vars
from app.services.region_models import current_region, is_inference_profile_id, repoint_regional_prefix
from app.services.runtime_deployer import _build_network_configuration

logger = logging.getLogger(__name__)


class _NoAliasDumper(yaml.SafeDumper):
    """A dumper that repeats a shared node instead of aliasing it.

    CloudFormation rejects YAML anchors and aliases outright:
    ``Template error: YAML aliases are not allowed in CloudFormation templates``,
    at CreateChangeSet, before it looks at a single resource. PyYAML emits them
    whenever the same object is reachable from two places in the tree, which is easy
    to do by accident with a module-level constant like a ``{"Ref": ...}`` and
    impossible to see afterwards — the emitted template still round-trips through
    ``yaml.safe_load`` to exactly the right structure, and reads correctly to a human.

    So this is a backstop, not the fix: the shared objects are also gone (see
    ``_customer_key_ref``). It is here because the failure is total, silent until a
    real deploy, and one careless shared dict away at any time.
    """

    def ignore_aliases(self, data):  # noqa: ANN001, ANN201 - PyYAML's own signature
        return True


def _dump_template(template: dict) -> str:
    return yaml.dump(
        template,
        Dumper=_NoAliasDumper,
        default_flow_style=False,
        sort_keys=False,
        allow_unicode=True,
    )


# ---------------------------------------------------------------------------
# Data-bearing resource protection
# ---------------------------------------------------------------------------

# ARCC guidance "Protect storage resources from accidental deletion or
# replacement" (cnt_h02wszR9St529D) requires BOTH DeletionPolicy and
# UpdateReplacePolicy on every storage-capacity resource, because a replacing
# update is just as destructive as a delete and only DeletionPolicy is widely
# remembered. Its exit criterion is exactly that: "Define DeletionPolicy and
# UpdateReplacePolicy for storage resources in your CloudFormation template."
#
# Keyed on resource TYPE, not logical id, on purpose. A name-keyed list silently
# stops protecting a resource the day somebody renames it or adds a second one —
# and this template already has two Cognito user pools (the gateway pool and the
# MCP-server pool) for exactly that reason. Adding a new data-bearing type is the
# only change that needs a human here.
DATA_BEARING_RESOURCE_TYPES = frozenset(
    {
        "AWS::Cognito::UserPool",  # user identities
        "AWS::Bedrock::KnowledgeBase",  # vector index + ingested documents
        "AWS::Bedrock::DataSource",  # ingestion state for the above
        "AWS::BedrockAgentCore::Memory",  # conversation history
        "AWS::S3Vectors::VectorBucket",  # the embeddings themselves
        "AWS::S3Vectors::Index",  # every property is createOnly: an update REPLACES it
        # Logs are data. They are the only record of what the agent was asked and
        # what it answered, so a stack delete should not silently be what destroys
        # an audit trail — but a demo stack should still be able to opt out, which
        # is exactly what the retention policy is for. Stamped here rather than
        # hardcoded Retain in _apply_lambda_log_groups so there is one knob, not two.
        "AWS::Logs::LogGroup",
    }
)


# Resources that hold no data themselves, but without which a RETAINED data resource
# cannot be deleted afterwards. Retaining data and then destroying the only means of
# disposing of it is not protection; it is a resource the operator can never remove.
#
# Proven live in us-east-1, then re-proven with a control against real ingested
# vectors (stacks rtn0919-retain, kbretain-0919150116, kbctl-0919150613).
#
# The purge runs when the DATA SOURCE is deleted, using this role — measured, not
# assumed: list-vectors went 1 -> 0 on delete-data-source, before the knowledge base
# was touched. AWS::Bedrock::KnowledgeBase re-attempts the same purge on its own
# delete, naming the same data source id in failureReasons, so both deletes fail if
# the role is gone. Worth keeping straight, because an operator reading only "the
# knowledge base purges its vectors" debugs the wrong API call.
#
# With the role retained: data source and knowledge base both delete first time.
# With the role deleted first and the vector store fully intact — the pre-fix
# situation, in the textbook order — delete-data-source returns DELETE_UNSUCCESSFUL,
# "Unable to delete data from vector store", the vector count stays at 1, and the
# knowledge base then fails the same way. Recreating ONLY the role, touching nothing
# else, makes the identical delete succeed and the count go to 0. So the role is the
# whole cause and deletion ordering is not a mitigation. The role's inline Policies
# block travels with it byte-identical across the stack delete (same policy sha256
# before and after) and is sufficient on its own.
#
# Keyed by the data resource's TYPE, for the same reason DATA_BEARING_RESOURCE_TYPES
# is: a logical-id list stops protecting anything the day somebody renames a resource.
# The generalisable question when adding a type here is "what does this resource need
# in order to delete ITSELF, and is that retained too?"
DELETION_DEPENDENCIES: dict[str, tuple[str, ...]] = {
    "AWS::Bedrock::KnowledgeBase": ("KnowledgeBaseRole",),
}


def _apply_deletion_dependencies(template: dict, policy: str) -> list[str]:
    """Retain whatever a retained data resource needs in order to be deletable.

    Only meaningful for ``Retain``: under ``Delete`` the data resource goes with the
    stack, so nothing has to outlive it, and leaving an IAM role behind would be a
    gratuitous orphan.

    The alternative — which this replaces — was to tell the operator in teardown.sh
    to recreate the role by hand. That is worse on two counts. It is a multi-step
    recipe run against a stack that no longer exists, and the trust-and-permissions
    policy an operator can be told to paste in a shell one-liner is far broader than
    the one the template had (``s3vectors:*`` on ``*``), so the documented workaround
    ended by advising exactly the unconditioned wildcard ARCC cnt_SFJJhkOueCPRkd
    warns against. Retaining the real, already-scoped role avoids both.
    """
    if policy != "Retain":
        return []

    present = {resource.get("Type") for resource in template.get("Resources", {}).values()}
    touched = []
    for data_type, dependency_ids in DELETION_DEPENDENCIES.items():
        if data_type not in present:
            continue
        for logical_id in dependency_ids:
            resource = template.get("Resources", {}).get(logical_id)
            if resource is None:
                # Not a silent skip: the mapping naming a resource this template does
                # not have means the two have drifted, and the consequence is an
                # un-deletable retained resource in the customer's account.
                logger.warning(
                    "DELETION_DEPENDENCIES names %s for %s, but this template has no such "
                    "resource: a retained %s may not be deletable",
                    logical_id,
                    data_type,
                    data_type,
                )
                continue
            resource["DeletionPolicy"] = "Retain"
            resource["UpdateReplacePolicy"] = "Retain"
            touched.append(logical_id)
    return sorted(touched)


def _apply_data_retention(template: dict, policy: str) -> list[str]:
    """Stamp *policy* onto every data-bearing resource. Returns the ids touched.

    The returned list is not decoration: the generated README enumerates it, and
    the test suite asserts it is non-empty for every component combination that
    creates data. A silent empty return is the failure mode to catch.
    """
    if policy not in ("Retain", "Delete"):
        raise ValueError(f"data retention policy must be Retain or Delete, got {policy!r}")

    touched = []
    for logical_id, resource in template.get("Resources", {}).items():
        if resource.get("Type") in DATA_BEARING_RESOURCE_TYPES:
            resource["DeletionPolicy"] = policy
            resource["UpdateReplacePolicy"] = policy
            touched.append(logical_id)
        if resource.get("Type") == "AWS::Cognito::UserPool":
            # Cognito's own guard, stamped from the same knob rather than hardcoded,
            # because the two MUST agree or teardown deadlocks: DeletionProtection
            # ACTIVE makes DeleteUserPool fail outright, so a Delete-retention stack
            # would hang its own teardown on the resource it was told to remove.
            # Retain pairs with ACTIVE for the mirror-image reason — there the pool is
            # meant to outlive the stack, and a surviving user directory with no guard
            # is one console click or one stray DeleteUserPool call from taking every
            # identity with it, with nothing to roll back to.
            resource.setdefault("Properties", {})["DeletionProtection"] = "ACTIVE" if policy == "Retain" else "INACTIVE"
    return sorted(touched)


def _split_retained(template: dict, retained: list[str]) -> tuple[list[str], list[str]]:
    """Separate retained log groups from retained data stores. Returns (logs, stores).

    They need different words and carry different consequences, and conflating them
    made the teardown notice wrong in the commonest case. A runtime-only export
    retains exactly one resource — the CFN provider Lambda's log group — and the
    notice told the operator it "holds user identities, ingested documents and/or
    conversation history". None of that is in a Lambda log group, and a warning that
    is wrong once is a warning the operator stops reading, which is the whole reason
    the quiet-when-there-is-nothing-to-lose rule exists.

    The consequence is specific to log groups, too: a retained group makes a
    redeploy under the same stack name fail at
    ``[AWS::EarlyValidation::ResourceExistenceCheck]``, which reports ``"Hooks": []``
    and names no resource. The operator cannot act on that error without being told
    beforehand what to delete, so the notice below hands them the command.
    """
    resources = template.get("Resources", {})
    logs = [r for r in retained if resources.get(r, {}).get("Type") == "AWS::Logs::LogGroup"]
    return logs, [r for r in retained if r not in set(logs)]


# ---------------------------------------------------------------------------
# Role governance: permissions boundary and optional role naming
# ---------------------------------------------------------------------------

PERMISSIONS_BOUNDARY_CONDITION = "HasPermissionsBoundary"
EXPLICIT_ROLE_NAMES_CONDITION = "HasExplicitRoleNames"


# Confused-deputy protection for the service-principal trust policies.
#
# A role trust policy is a resource policy. When it names only a service — as every
# role here did — the service will assume the role for *any* caller it acts for,
# including one in another AWS account who persuades the same service to reach into
# this one. ARCC cnt_vBC0kXE8PNHqrW requires service-to-service access to be
# constrained with the aws:SourceAccount / aws:SourceArn condition keys, which the
# calling service populates from x-amz-source-account / x-amz-source-arn.
#
# The condition can only be added where the service is known to send those headers:
# a service that does not will simply fail to assume the role, and the failure
# surfaces as an unrelated-looking resource error at deploy time. So this map is an
# allowlist of the principals confirmed to send them, not every principal we emit.
#
#   bedrock.amazonaws.com          — AWS documents exactly this trust policy for a
#                                    Knowledge Base service role, both keys.
#   bedrock-agentcore.amazonaws.com — verified live on two independent paths, each
#                                    with a wrong-value negative control, which is
#                                    what makes the pass meaningful: an absent
#                                    context key makes StringEquals and ArnLike
#                                    evaluate false, so if AgentCore did not send
#                                    the headers the correct-account arm would have
#                                    failed too. Gateway: stack CREATE_COMPLETE and
#                                    a real MCP tools/call returned the Lambda's own
#                                    output; a deliberately wrong account and a
#                                    deliberately wrong ARN both rolled back.
#                                    Memory: CreateMemory reached ACTIVE, and both
#                                    wrong values were rejected with "Please provide
#                                    a role with a valid trust policy".
#   lambda.amazonaws.com           — not applicable. Lambda assumes the execution
#                                    role for a function in this account only, and
#                                    AWS does not document these keys for it.
#
# Do NOT narrow the resource portion of aws:SourceArn below. The source ARN is the
# ARN of the *calling AgentCore resource*, so it is gateway/... for a gateway role
# and memory/... for a memory execution role. One shared entry narrowed to
# ``gateway/*`` passes every gateway test and then breaks every memory deploy — that
# was tested, not guessed. Tightening it further means emitting the condition per
# role type rather than per service principal.
#
# One note for whoever debugs a regression here: the AgentCore failure does not
# surface on the role. It surfaces at *target* creation, as
# "Gateway service is not authorized to perform AssumeRole on Gateway role. Update
# trust policy and retry", against the AWS::BedrockAgentCore::GatewayTarget — two
# resources after the cause.
_TRUST_SOURCE_CONDITIONS: dict[str, dict] = {
    "bedrock.amazonaws.com": {
        "StringEquals": {"aws:SourceAccount": {"Ref": "AWS::AccountId"}},
        "ArnLike": {"aws:SourceArn": {"Fn::Sub": "arn:${AWS::Partition}:bedrock:${AWS::Region}:${AWS::AccountId}:*"}},
    },
    "bedrock-agentcore.amazonaws.com": {
        "StringEquals": {"aws:SourceAccount": {"Ref": "AWS::AccountId"}},
        "ArnLike": {
            "aws:SourceArn": {"Fn::Sub": "arn:${AWS::Partition}:bedrock-agentcore:${AWS::Region}:${AWS::AccountId}:*"}
        },
    },
}


def _apply_trust_source_conditions(statement: dict) -> bool:
    """Constrain one trust statement to this account, if its principal supports it.

    Returns whether a condition was added, so the caller can report the count and a
    test can assert the pass is not silently doing nothing.
    """
    service = statement.get("Principal", {}).get("Service")
    condition = _TRUST_SOURCE_CONDITIONS.get(service)
    if not condition:
        return False
    # Merge rather than assign: a caller-supplied condition on the same statement
    # would otherwise be dropped, which would loosen the policy while appearing to
    # tighten it.
    existing = statement.setdefault("Condition", {})
    for operator, keys in condition.items():
        existing.setdefault(operator, {}).update(keys)
    return True


def _apply_role_governance(template: dict) -> list[str]:
    """Make every emitted role boundary-aware and its name optional.

    Two things a regulated account routinely mandates and this template gave it
    no way to express.

    A permissions boundary is the control that lets a security team allow a
    workload to create its own roles at all: it caps what those roles can ever be
    granted, no matter what the stack asks for. Without a boundary parameter the
    recipient's only options were to hand the deploying principal unbounded
    iam:CreateRole or not deploy.

    Explicit ``RoleName`` values were the other blocker. Eight roles set one, so
    the stack always required ``CAPABILITY_NAMED_IAM`` — which many accounts deny
    outright — and the fixed ``AgentCore*-`` prefix collides with accounts whose
    SCPs or naming conventions mandate their own. Named roles stay the default
    because they are far easier to find in an audit, but setting
    ``UseExplicitRoleNames=false`` lets CloudFormation generate the names and the
    stack then deploys under plain ``CAPABILITY_IAM``.

    Both are applied in one pass over the finished Resources block for the same
    reason as ``_apply_data_retention``: a future branch that adds a role cannot
    forget to opt in. Returns the role ids touched.
    """
    template.setdefault("Conditions", {}).update(
        {
            PERMISSIONS_BOUNDARY_CONDITION: {"Fn::Not": [{"Fn::Equals": [{"Ref": "PermissionsBoundaryArn"}, ""]}]},
            EXPLICIT_ROLE_NAMES_CONDITION: {"Fn::Equals": [{"Ref": "UseExplicitRoleNames"}, "true"]},
        }
    )
    touched = []
    for logical_id, resource in template.get("Resources", {}).items():
        if resource.get("Type") != "AWS::IAM::Role":
            continue
        properties = resource.setdefault("Properties", {})
        properties["PermissionsBoundary"] = {
            "Fn::If": [PERMISSIONS_BOUNDARY_CONDITION, {"Ref": "PermissionsBoundaryArn"}, {"Ref": "AWS::NoValue"}]
        }
        if "RoleName" in properties:
            properties["RoleName"] = {
                "Fn::If": [EXPLICIT_ROLE_NAMES_CONDITION, properties["RoleName"], {"Ref": "AWS::NoValue"}]
            }
        for statement in properties.get("AssumeRolePolicyDocument", {}).get("Statement", []):
            _apply_trust_source_conditions(statement)
        touched.append(logical_id)
    return sorted(touched)


# ---------------------------------------------------------------------------
# Customer-managed encryption keys
# ---------------------------------------------------------------------------

CUSTOMER_KEY_CONDITION = "HasCustomerManagedKey"


# A factory, not a shared constant, and the difference is not cosmetic. One dict
# object referenced from several places in the template makes yaml.dump emit a YAML
# anchor and aliases (&id001 / *id001) instead of repeating the mapping, and
# CloudFormation refuses the whole template with "Template error: YAML aliases are
# not allowed in CloudFormation templates" — before it creates a single resource.
# The template still round-trips through yaml.safe_load perfectly and looks correct
# to a reader, so nothing but a real deploy or an explicit assertion catches it.
# Proven live: a bundle whose deploy.sh had already built the dependency bundle,
# created the bucket and uploaded all three artifacts failed at CreateChangeSet with
# exactly that error. _dump_template's NoAliasDumper is the second half of the fix;
# this half stops the aliases existing, that half makes them unrepresentable.
def _customer_key_ref() -> dict:
    return {"Ref": "CustomerManagedKeyArn"}


# Resource type -> (property name, property value when a key is supplied).
#
# Every entry was read off the live CloudFormation registry
# (``aws cloudformation describe-type --type RESOURCE --type-name <type>``), not
# off documentation, because the property names are not consistent even within one
# service: AgentCore Memory and PolicyEngine say EncryptionKeyArn, AgentCore
# Gateway says KmsKeyArn, S3 Vectors says EncryptionConfiguration.KmsKeyArn and
# needs SseType flipped to aws:kms alongside it, and Bedrock DataSource nests it
# one level down again.
#
# Three types in this template deliberately have NO entry, and their absence is a
# finding rather than an omission:
#   AWS::Bedrock::KnowledgeBase   - no encryption property exists. The KB's vector
#                                   data is encrypted by the S3 Vectors bucket and
#                                   index below, and its ingestion state by the
#                                   data source; there is nothing left on the KB.
#   AWS::BedrockAgentCore::Runtime - no encryption property exists.
#   AWS::Cognito::UserPool         - no encryption property exists; Cognito does
#                                   not support a customer-managed key at rest.
# So a customer-managed key covers conversation memory, embeddings and ingestion
# state. It does not cover the user directory. The generated README says so.
# The second element is a *factory* for the same reason ``_customer_key_ref`` is one:
# a value shared between two resources becomes a YAML alias and the template is then
# rejected outright.
CUSTOMER_KEY_PROPERTIES: dict[str, tuple[str, Callable[[], object]]] = {
    "AWS::BedrockAgentCore::Memory": ("EncryptionKeyArn", _customer_key_ref),
    "AWS::BedrockAgentCore::Gateway": ("KmsKeyArn", _customer_key_ref),
    "AWS::S3Vectors::VectorBucket": (
        "EncryptionConfiguration",
        lambda: {"SseType": "aws:kms", "KmsKeyArn": _customer_key_ref()},
    ),
    "AWS::S3Vectors::Index": (
        "EncryptionConfiguration",
        lambda: {"SseType": "aws:kms", "KmsKeyArn": _customer_key_ref()},
    ),
    "AWS::Bedrock::DataSource": (
        "ServerSideEncryptionConfiguration",
        lambda: {"KmsKeyArn": _customer_key_ref()},
    ),
    # The policy engine stores the Cedar statements themselves — who may invoke
    # which tool. Read off the live registry like the rest; the property is
    # createOnly, so supplying a key to a stack that already has an engine
    # REPLACES the engine. That is survivable here and nowhere else in this table:
    # the statements are rebuilt from the template by Custom::AgentCorePolicy,
    # which already DependsOn the engine, so a replacement re-creates them rather
    # than losing them. It does mean the engine id changes, which is why the
    # gateway's PolicyEngineConfiguration reads it with Fn::GetAtt.
    "AWS::BedrockAgentCore::PolicyEngine": ("EncryptionKeyArn", _customer_key_ref),
    # Lambda's KmsKeyArn encrypts the function's environment variables at rest.
    # Only applied to functions that HAVE environment variables — see
    # _apply_customer_key. Found by Checkov CKV_AWS_173 on the emitted template.
    "AWS::Lambda::Function": ("KmsKeyArn", _customer_key_ref),
    # The log groups. Unlike every other entry, the key is used by the CloudWatch
    # Logs *service* rather than by one of this stack's roles, so no inline policy
    # can authorize it — the key policy has to name the
    # logs.<region>.amazonaws.com service principal, and CreateLogGroup fails
    # outright if it does not. That requirement is why this entry was originally
    # left out; the generated README's key-policy section now carries the statement.
    # Found by Checkov CKV_AWS_158.
    "AWS::Logs::LogGroup": ("KmsKeyId", _customer_key_ref),
    # The AgentCore runtime's OWN log groups — the ones holding the conversation.
    # AWS::BedrockAgentCore::Runtime has no logging or encryption property at all (see
    # the note above), and the service creates these groups outside CloudFormation, so
    # Custom::RuntimeLogGroup is the only thing that can reach them. It passes this ARN
    # to CreateLogGroup/AssociateKmsKey, and the same logs.<region>.amazonaws.com
    # key-policy statement the entry above needs is what makes that work.
    "Custom::RuntimeLogGroup": ("KmsKeyArn", _customer_key_ref),
}

# Role logical id -> the encrypted resource types that role has to be able to use
# the key for. A static "grant every role kms:Decrypt" list would undo the
# least-privilege work in _apply_role_governance's neighbours: the runtime role
# exists in every combination, so it would carry key access even in a stack with
# nothing encrypted. Keyed this way, a role only gets the grant when a resource it
# actually touches is in the template.
CUSTOMER_KEY_ROLE_DEPENDENCIES: dict[str, frozenset[str]] = {
    "RuntimeExecutionRole": frozenset({"AWS::BedrockAgentCore::Memory", "AWS::BedrockAgentCore::Gateway"}),
    "MemoryExecutionRole": frozenset({"AWS::BedrockAgentCore::Memory"}),
    "GatewayRole": frozenset({"AWS::BedrockAgentCore::Gateway"}),
    "KnowledgeBaseRole": frozenset(
        {"AWS::S3Vectors::VectorBucket", "AWS::S3Vectors::Index", "AWS::Bedrock::DataSource"}
    ),
    # The custom-resource Lambda writes the Cedar statements into the engine, so an
    # encrypted engine makes it a key user. Stated explicitly rather than left to
    # the Lambda-environment inference below, because the grant is needed for a
    # different reason: AgentCore's policy APIs run a forward-access-session KMS
    # check against the caller, and a role without kms:Decrypt on the engine's key
    # gets an AccessDenied from the *policy* call, not a decrypt error.
    # Custom::RuntimeLogGroup for the same class of reason: the Lambda hands the key
    # ARN to CreateLogGroup/AssociateKmsKey, and CloudWatch Logs validates the key as
    # the caller before accepting it. A role holding logs:AssociateKmsKey but nothing
    # on the key gets an AccessDenied from the LOGS call, which reads as a log-group
    # permission problem and is not one. This entry is why the whole feature works
    # from a least-privilege role rather than only from an administrator's.
    "CfnProviderRole": frozenset({"AWS::BedrockAgentCore::PolicyEngine", "Custom::RuntimeLogGroup"}),
}

CUSTOMER_KEY_POLICY_NAME = "CustomerManagedKeyAccess"


def _customer_key_policy() -> dict:
    """The inline policy a role needs to use the supplied key.

    ``Resource`` is the single supplied key ARN — the whole point of the feature is
    that the customer can revoke it, so a wildcard here would be self-defeating.

    ``kms:CreateGrant`` is here because the AWS services holding this data create
    grants on the caller's behalf rather than calling Decrypt directly. Per ARCC
    cnt_SFJJhkOueCPRkd it carries the ``kms:GrantIsForAWSResource`` condition, which
    is what stops the grant being usable to hand the key to an arbitrary principal:
    KMS only honours the call when the grantee is an AWS service acting for this
    request.
    """
    return {
        "PolicyName": CUSTOMER_KEY_POLICY_NAME,
        "PolicyDocument": {
            "Version": "2012-10-17",
            "Statement": [
                {
                    "Sid": "UseCustomerManagedKey",
                    "Effect": "Allow",
                    "Action": [
                        "kms:Decrypt",
                        "kms:GenerateDataKey",
                        # The envelope-encryption variant, and the one that is easy
                        # to leave out: a service that only ever needs the wrapped
                        # data key never calls GenerateDataKey. Its absence showed up
                        # live as "missing required kms:GenerateDataKeyWithoutPlaintext
                        # permission" — and only for a least-privilege caller, so an
                        # AdministratorAccess deploy proves nothing about it.
                        "kms:GenerateDataKeyWithoutPlaintext",
                        "kms:DescribeKey",
                    ],
                    "Resource": _customer_key_ref(),
                },
                {
                    "Sid": "GrantCustomerManagedKeyToAwsResources",
                    "Effect": "Allow",
                    "Action": "kms:CreateGrant",
                    "Resource": _customer_key_ref(),
                    "Condition": {"Bool": {"kms:GrantIsForAWSResource": "true"}},
                },
            ],
        },
    }


def _apply_customer_key(template: dict) -> tuple[list[str], list[str]]:
    """Wire the optional customer-managed key through the finished template.

    Returns ``(encrypted resource ids, roles granted key access)``. Both are used
    by the generated README and pinned by the contract tests, so a branch that adds
    an encryptable resource and forgets it shows up as an empty list rather than as
    silently unencrypted data.

    Applied in one pass at the end for the same reason as ``_apply_data_retention``
    and ``_apply_role_governance``: keying on resource type means a future
    ``_add_*`` call cannot forget to opt in.
    """
    template.setdefault("Conditions", {})[CUSTOMER_KEY_CONDITION] = {
        "Fn::Not": [{"Fn::Equals": [_customer_key_ref(), ""]}]
    }

    resources = template.get("Resources", {})
    encrypted: list[str] = []
    present_types: set[str] = set()
    # Roles derived from the template rather than declared: a Lambda whose
    # environment is encrypted with a customer key cannot start unless its own
    # execution role holds kms:Decrypt on that key, and the role is right there in
    # the function's Role property. Reading it beats maintaining a second list that
    # can fall out of step with which functions exist.
    lambda_roles: set[str] = set()

    for logical_id, resource in resources.items():
        resource_type = resource.get("Type", "")
        mapping = CUSTOMER_KEY_PROPERTIES.get(resource_type)
        if mapping is None:
            continue
        properties = resource.setdefault("Properties", {})

        if resource_type == "AWS::Lambda::Function":
            if "Environment" not in properties:
                # Nothing of ours to encrypt. On a function with no environment
                # variables KmsKeyArn covers only SnapStart snapshots, which this
                # template does not use, so setting it would buy nothing and cost
                # the function's role a kms:Decrypt grant. Checkov's CKV_AWS_173
                # scopes itself the same way.
                continue
            role = properties.get("Role")
            get_att = role.get("Fn::GetAtt") if isinstance(role, dict) else None
            if get_att:
                lambda_roles.add(get_att[0])

        name, build_value = mapping
        properties[name] = {"Fn::If": [CUSTOMER_KEY_CONDITION, build_value(), {"Ref": "AWS::NoValue"}]}
        encrypted.append(logical_id)
        present_types.add(resource_type)

    needs_key = set(lambda_roles)
    for role_id, needed_types in CUSTOMER_KEY_ROLE_DEPENDENCIES.items():
        if needed_types & present_types:
            needs_key.add(role_id)

    granted: list[str] = []
    for role_id in sorted(needs_key):
        role = resources.get(role_id)
        if role is None or role.get("Type") != "AWS::IAM::Role":
            continue
        policies = role.setdefault("Properties", {}).setdefault("Policies", [])
        # Fn::If on the list entry, not on the whole Policies list: the other
        # inline policies must survive when no key is supplied.
        policies.append({"Fn::If": [CUSTOMER_KEY_CONDITION, _customer_key_policy(), {"Ref": "AWS::NoValue"}]})
        granted.append(role_id)

    return sorted(encrypted), sorted(granted)


# ---------------------------------------------------------------------------
# Resource scoping for the emitted policies
# ---------------------------------------------------------------------------
#
# ARCC cnt_AGx9pUNpmdOVZB: specific actions on specific resources, not "*". The
# actions were already exact everywhere; the resources were "*" in eighteen
# statements. These helpers exist so that four roles that all invoke Bedrock
# cannot drift into four different answers about what a model ARN looks like, and
# so each remaining "*" is a deliberate, commented decision rather than a default.


def _bedrock_model_resources() -> list[dict]:
    """The ARN families ``bedrock:InvokeModel`` actually needs.

    Deliberately not the exported ``ModelId``: the parameter is overridable, and a
    policy pinned to the export-time value denies an operator who legitimately
    changes it — a failure that surfaces as a runtime AccessDenied, not a deploy
    error. The families below are the narrowing that survives that override.

    The region is wildcarded on the foundation-model family because that is what
    cross-region inference requires: invoking a ``us.`` inference profile calls the
    model in whichever region the profile routes to, and denying the other regions
    breaks the default configuration. Profiles stay account-scoped.
    """
    return [
        {"Fn::Sub": "arn:${AWS::Partition}:bedrock:*::foundation-model/*"},
        {"Fn::Sub": "arn:${AWS::Partition}:bedrock:*:${AWS::AccountId}:inference-profile/*"},
        {"Fn::Sub": "arn:${AWS::Partition}:bedrock:*:${AWS::AccountId}:application-inference-profile/*"},
    ]


def _bedrock_model_arn(model_id: str) -> dict:
    """The ARN that names *model_id* to Bedrock — profile or foundation model.

    A geography-prefixed id (``us.anthropic.claude-sonnet-5``) is a cross-region
    inference profile, not a foundation model, and profiles are account-qualified.
    Putting one under a ``foundation-model/`` path is accepted by CloudFormation and
    fails only when the Lambda runs, which is how it survived: proven live,
    ``RetrieveAndGenerate`` returned

        ValidationException ... Received validation exception when calling
        GetInferenceProfile for
        arn:aws:bedrock:us-east-1::foundation-model/us.anthropic.claude-sonnet-5

    on a stack that reached CREATE_COMPLETE with ``FunctionError: null`` — the error
    was in the response body, so even an invoke-based smoke test reads as a pass.
    Bedrock resolves the ``us.`` prefix as a profile and then cannot find one at that
    ARN. IAM was already correct here (``_bedrock_model_resources`` grants both
    families), so an IAM review passes it straight through.

    A plain on-demand id keeps the unqualified ``foundation-model/`` form, which is
    the correct shape for it; embedding models in particular have no profiles at all.
    ``${AWS::Partition}`` rather than a literal ``aws`` so the template is not
    silently wrong in GovCloud or China.
    """
    if is_inference_profile_id(model_id):
        return {
            "Fn::Sub": f"arn:${{AWS::Partition}}:bedrock:${{AWS::Region}}:${{AWS::AccountId}}"
            f":inference-profile/{model_id}"
        }
    return {"Fn::Sub": f"arn:${{AWS::Partition}}:bedrock:${{AWS::Region}}::foundation-model/{model_id}"}


def _log_group_resources() -> list[dict]:
    """Log groups in this account and region.

    One pattern, not two. ``PutLogEvents`` is authorized against the
    ``log-group:<name>:log-stream:<name>`` ARN while ``CreateLogGroup`` is
    authorized against ``log-group:<name>``, which looks like it needs both shapes
    listed — but an IAM ``*`` matches any character including ``:`` and ``/``, so
    the trailing wildcard already covers the stream ARN. IAM Access Analyzer
    reports the second entry as REDUNDANT_RESOURCE, which is how this was settled.

    The group name stays wildcarded because AgentCore derives it from the runtime
    id it mints at create time.
    """
    return [{"Fn::Sub": "arn:${AWS::Partition}:logs:${AWS::Region}:${AWS::AccountId}:log-group:*"}]


# Where AgentCore puts a runtime's own logs: one group per endpoint, named
# ``<prefix>/<runtimeId>-<qualifier>``. Verified live rather than read off the docs,
# and the finding that matters is the plural: a runtime with a named endpoint has BOTH
# ``-DEFAULT`` and ``-<endpointName>``, both created at stack-create time before any
# invoke, and the invoked qualifier is the one that receives the conversation.
RUNTIME_LOG_GROUP_PREFIX = "/aws/bedrock-agentcore/runtimes"


def _runtime_log_group_resources() -> list[dict]:
    """Only the AgentCore runtime log groups, for the governance custom resource.

    Deliberately narrower than ``_log_group_resources``: that one authorizes writing
    to any group in the account because AgentCore mints the name, while this
    authorizes *changing settings on* groups — including DisassociateKmsKey, which on
    the wrong group would make an unrelated team's existing log data unreadable. The
    runtime prefix is fixed by the service, so there is no reason for this to be wide.
    """
    return [
        {
            "Fn::Sub": (
                "arn:${AWS::Partition}:logs:${AWS::Region}:${AWS::AccountId}:"
                f"log-group:{RUNTIME_LOG_GROUP_PREFIX}/*"
            )
        }
    ]


# ---------------------------------------------------------------------------
# The AgentCore IAM prefix
# ---------------------------------------------------------------------------
#
# Every AgentCore action this template grants is prefixed ``bedrock-agentcore:``.
# There is no ``bedrock-agentcore-control:`` IAM prefix, and no
# ``agent-credential-provider:`` service at all. Both mistakes were in this file.
#
# The confusion is understandable: ``bedrock-agentcore`` and
# ``bedrock-agentcore-control`` are both real API endpoints and both have their own
# botocore client, so ``bedrock-agentcore-control:GetMemory`` reads like the
# control-plane counterpart of a data-plane call. But an IAM service prefix is the
# SigV4 *signing name*, not the endpoint prefix, and both of those clients report
# ``signingName: bedrock-agentcore``. One namespace covers both planes.
#
# This is a silent failure, which is why it survived. IAM accepts a policy naming a
# service that does not exist -- no validation error at PutRolePolicy, no error at
# stack create, and the stack goes CREATE_COMPLETE. The statement simply authorizes
# nothing, so the first denial appears at runtime, in a different place, as an
# AccessDeniedException on a call whose permission is visibly "granted" in the
# console. Two statements here were void in their entirety (evaluation access, and
# credential-provider access) and several others were half-void.
#
# Checked with two oracles rather than by reading documentation, because the two
# answer different questions:
#   * botocore's service models settle the PREFIX. `signingName` is the prefix, and
#     a service that is not in botocore at all (``agent-credential-provider``)
#     raises UnknownServiceError.
#   * IAM Access Analyzer (``validate-policy``) settles individual ACTIONS. IAM
#     actions do not map 1:1 to API operations -- AuthorizeAction,
#     PartiallyAuthorizeActions and InvokeGateway are all real IAM actions with no
#     SDK operation behind them, so "absent from botocore" does not mean invalid.
# An action was only changed where both oracles agreed. INVALID_SERVICE_IN_ACTION
# from Access Analyzer is the finding that catches the prefix error; add a new
# AgentCore grant and it is worth re-running.
def _agentcore_resources(*paths: str) -> list[dict]:
    """AgentCore resources of the given ``kind/*`` shapes in this account/region.

    The id stays wildcarded rather than being pinned with ``Fn::GetAtt`` for two
    reasons. The gateway role and the memory execution role are passed to the very
    resources they would have to name, so naming them is a circular dependency.
    And the AgentCore resource types publish no ``Arn`` attribute that this
    generator has verified — cfn-lint ships no schema for them either, so a wrong
    ``GetAtt`` would not fail the lint gate, it would fail the deploy.

    Account and region scoping is what is left, and it is not nothing: it stops a
    compromised runtime from reaching another region's or another account's
    gateway or memory, which "*" permitted outright.
    """
    return [
        {"Fn::Sub": f"arn:${{AWS::Partition}}:bedrock-agentcore:${{AWS::Region}}:${{AWS::AccountId}}:{path}"}
        for path in paths
    ]


def _agentcore_own_resource(logical_id: str, arn_attribute: str) -> list[dict]:
    """This stack's own AgentCore resource, by ARN, and its sub-resources.

    ``kind/*`` — which is what these statements used to say — is account-wide, and
    account-wide is not a theoretical problem here. Two agents exported from this
    platform into one account each get a runtime role that can call ``GetMemory``,
    ``ListActors`` and ``RetrieveMemoryRecords`` on *every* memory in the region,
    including the other agent's. That was proven, not inferred: a replica of one
    agent's runtime role read the other agent's memory and enumerated its end users'
    Cognito subject ids as actor ids. Conversation history and end-user identifiers
    are exactly the data a regulated recipient runs two agents to keep apart.

    ARCC cnt_AGx9pUNpmdOVZB: specific actions on specific resources. The action
    lists were already exact; this makes the resources exact too.

    Both types publish an ARN attribute — ``GatewayArn`` and ``MemoryArn``, verified
    against the CloudFormation resource registry (``describe-type``) rather than
    assumed, because a wrong ``GetAtt`` on these types does not fail cfn-lint: no
    schema ships for them, so it fails the deploy. Using the ARN attribute directly
    also avoids re-deriving the ARN shape from an id, which is the other way this
    goes wrong.

    The second entry covers sub-resources (a gateway's targets, a memory's records).
    An IAM ``*`` spans ``/``, so one trailing wildcard is enough.

    Only roles the resource does NOT depend on can use this. The gateway role and the
    memory execution role are passed to the very resources they would name, so for
    them this is a circular dependency and the answer is prefix scoping — see
    ``_agentcore_named_resources``.
    """
    # Two separate dicts rather than one bound to a name and used twice: a shared
    # object is what makes yaml.dump emit an anchor and an alias, which CloudFormation
    # rejects outright. _NoAliasDumper is the backstop; not creating them is the fix.
    # See _customer_key_ref.
    return [
        {"Fn::GetAtt": [logical_id, arn_attribute]},
        {"Fn::Join": ["", [{"Fn::GetAtt": [logical_id, arn_attribute]}, "/*"]]},
    ]


def _agentcore_named_resources(*patterns: str) -> list[dict]:
    """AgentCore resources whose names this stack chose, for the circular cases.

    The gateway role is passed to the gateway and the memory execution role to the
    memory, so neither can name its own resource's ARN without a dependency cycle.
    What they *can* do is scope to the names this template asks for:
    ``${DeploymentName}-gateway`` and ``${DeploymentName}_memory``, to which the
    service appends ``-<10 chars>``. That is strictly narrower than ``kind/*`` and
    needs no attribute, so it cannot be wrong about a shape.

    It is weaker than ``_agentcore_own_resource``: a second stack deployed with the
    same ``DeploymentName`` would be in scope. It cannot exist — these names have to
    be unique in the account — but say so rather than imply exactness.
    """
    return _agentcore_resources(*patterns)


def _agentcore_secret_resources() -> list[dict]:
    """The Secrets Manager namespaces AgentCore identity actually uses.

    ``CreateOauth2CredentialProvider`` stores its client secret as
    ``bedrock-agentcore-identity!default/oauth2/<name>``; older paths used an
    ``agentcore-`` prefix. Both are listed because a deploy that lands on the other
    one fails at create time, and neither reaches a secret this stack does not own.
    """
    return [
        {"Fn::Sub": "arn:${AWS::Partition}:secretsmanager:${AWS::Region}:${AWS::AccountId}:secret:bedrock-agentcore-*"},
        {"Fn::Sub": "arn:${AWS::Partition}:secretsmanager:${AWS::Region}:${AWS::AccountId}:secret:agentcore-*"},
    ]


LAMBDA_CONCURRENCY_CONDITION = "HasLambdaConcurrencyLimit"


def _apply_lambda_concurrency(template: dict) -> list[str]:
    """Cap this stack's Lambda concurrency when the recipient asks for a cap.

    Separate pass rather than a property on each ``_add_*`` for the same reason as
    its neighbours: a future Lambda cannot be added without the knob.
    """
    template.setdefault("Conditions", {})[LAMBDA_CONCURRENCY_CONDITION] = {
        "Fn::Not": [{"Fn::Equals": [{"Ref": "LambdaReservedConcurrency"}, -1]}]
    }
    touched = []
    for logical_id, resource in template.get("Resources", {}).items():
        if resource.get("Type") != "AWS::Lambda::Function":
            continue
        resource.setdefault("Properties", {})["ReservedConcurrentExecutions"] = {
            "Fn::If": [
                LAMBDA_CONCURRENCY_CONDITION,
                {"Ref": "LambdaReservedConcurrency"},
                {"Ref": "AWS::NoValue"},
            ]
        }
        touched.append(logical_id)
    return sorted(touched)


COGNITO_DOMAIN_SUFFIX_CONDITION = "HasCognitoDomainSuffix"

# 12 hex characters, so "ac-mcp-" + a 40-char DeploymentName + "-" + this stays
# inside the 63-character limit on a Cognito hosted-UI domain prefix. It is also
# exactly the length of an AWS account id, which is what a recipient upgrading an
# existing stack has to pin here.
_COGNITO_DOMAIN_SUFFIX_PATTERN = "^[a-z0-9]{0,12}$"


def _stack_id_suffix() -> dict:
    """The last field of this stack's UUID: 12 hex characters, unique per stack.

    Replaces ``${AWS::AccountId}``, which the Cognito hosted-UI domain published:
    that domain resolves in public DNS and answers unauthenticated OIDC discovery
    with HTTP 200, so anyone who could guess the deployment name could read the
    account id out of the response. An account id is not a secret, but it is the
    first thing needed to aim anything at an account, and there is no reason to hand
    it out to make a name unique.

    It also fixes a collision the account id caused rather than prevented: two
    stacks with the same ``DeploymentName`` in one account derived the *same* domain,
    and the second one failed mid-create on AWS::Cognito::UserPoolDomain. The stack
    id is unique per stack, which is the uniqueness actually wanted here.

    A factory rather than a constant for the reason ``_customer_key_ref`` is one:
    the gateway pool and the MCP-server pool both use it, and a dict shared between
    two resources is emitted as a YAML alias, which CloudFormation rejects outright.
    """
    stack_uuid = {"Fn::Select": [2, {"Fn::Split": ["/", {"Ref": "AWS::StackId"}]}]}
    return {"Fn::Select": [4, {"Fn::Split": ["-", stack_uuid]}]}


def _cognito_domain(prefix: str) -> dict:
    """A hosted-UI domain prefix for *prefix* (``ac`` or ``ac-mcp``).

    The suffix parameter exists for one case only: a recipient updating a stack that
    was created before this change. ``Domain`` is createOnly, so changing it
    REPLACES the domain and every caller's token endpoint moves with it; pinning the
    old ``${AWS::AccountId}`` value keeps the existing URL working.
    """
    return {
        "Fn::If": [
            COGNITO_DOMAIN_SUFFIX_CONDITION,
            {"Fn::Sub": prefix + "-${DeploymentName}-${CognitoDomainSuffix}"},
            {"Fn::Sub": [prefix + "-${DeploymentName}-${StackSuffix}", {"StackSuffix": _stack_id_suffix()}]},
        ]
    }


def _add_cognito_parameters(template: dict) -> None:
    """Parameters shared by both emitted Cognito pools. Idempotent.

    Called from both ``_add_cognito`` and ``_add_mcp_server_cognito`` because either
    may be the only one present, and the "everything" canvas emits both.
    """
    template["Parameters"].setdefault(
        "CognitoDomainSuffix",
        {
            "Type": "String",
            "Default": "",
            "AllowedPattern": _COGNITO_DOMAIN_SUFFIX_PATTERN,
            "ConstraintDescription": "up to 12 lowercase letters or digits, or empty",
            "Description": (
                "Leave empty. The hosted-UI domain is then suffixed with this stack's own id, "
                "which is unique and publishes nothing about the account. Set this ONLY when "
                "updating a stack created before the suffix changed, to the AWS account id the "
                "old domain used, so the existing token endpoint keeps working."
            ),
        },
    )
    template["Parameters"].setdefault(
        "AccessTokenValidityMinutes",
        {
            "Type": "Number",
            "Default": 60,
            "MinValue": 5,
            "MaxValue": 1440,
            "Description": (
                "Lifetime of the OAuth access tokens these pools issue. 60 is Cognito's own "
                "default and what this stack used implicitly; lower it to shorten the window in "
                "which a leaked token is usable. Callers use the client-credentials grant, so "
                "they simply request another token - there are no refresh tokens to consider."
            ),
        },
    )
    template.setdefault("Conditions", {})[COGNITO_DOMAIN_SUFFIX_CONDITION] = {
        "Fn::Not": [{"Fn::Equals": [{"Ref": "CognitoDomainSuffix"}, ""]}]
    }


def _add_policy_parameters(template: dict) -> None:
    """The knob on how strictly AgentCore validates the emitted Cedar policies.

    Idempotent, and added only on the path that emits a policy engine, so a template
    without one does not carry a parameter that controls nothing.

    An earlier version of this docstring explained the lenient default with a race:
    FAIL_ON_ANY_FINDINGS runs a findings analysis that calls the gateway, the gateway
    was created moments earlier, and engine-to-gateway authorization had not converged.
    That explanation was wrong, and the wrong part mattered. ``Insufficient permissions
    to call gateway with ID <id>`` was a missing IAM grant on ``CfnProviderRole``, and it
    failed CreatePolicy under BOTH modes — so the shipped default never avoided it. A
    controlled live experiment settled it: same principal, same statement, gateway READY
    for many minutes, ``bedrock-agentcore:InvokeGateway`` on that one gateway ARN as the
    only variable. Without it, CREATE_FAILED in both modes; with it, ACTIVE in both. The
    grant is now part of AgentCorePolicyGatewayResolution, so a policy naming real tools
    can be created at all — which, before, it could not.

    Why the default is still the *lenient* value, which is the opposite of what a
    security review expects. Not a race: FAIL_ON_ANY_FINDINGS makes any finding fail the
    stack, including a finding about a statement the RECIPIENT supplied, and rolling back
    a whole deployment over an advisory finding on someone's own Cedar is not a default
    worth shipping. Measured live, a permit-all is also rejected under strict mode
    *asynchronously*: the call returns 200/CREATING and only the status poll in the
    custom resource catches it. What keeps the policy safe either way is that it names
    each tool explicitly and AgentCore is default-deny, plus two rejections
    IGNORE_ALL_FINDINGS does *not* skip: a wildcard resource, and a gateway that does not
    exist. Strict mode is a supported choice now rather than a trap, and that claim was
    earned rather than reasoned: a generated gateway+policy export was deployed twice
    from this bundle, once per mode, and the generated default permit reached ACTIVE with
    no statusReasons both times. So a recipient who wants findings to gate the deploy can
    set it.

    What the grant costs is real and is not hidden: for the life of the deploy, the
    custom-resource Lambda can invoke the tools this stack's gateway fronts. It is
    scoped to that gateway's ARN and its targets, never account-wide, and README >
    Authorization says so outright. The alternative was shipping a policy resource that
    cannot reach ACTIVE, which is not a security posture — it is a broken feature that
    leaves the gateway's authorization to whatever default-deny does on its own.

    Only the strictness-increasing direction is offered. ``enforcementMode`` is
    deliberately NOT a parameter: its other value, LOG_ONLY, *records* a denial instead
    of enforcing it, so an engine whose policies are all LOG_ONLY permits everything
    while looking exactly like one that does not. This template's entire authorization
    story is that the gateway denies tools the policy does not name, and a parameter
    that can quietly switch that off is not a knob worth shipping.
    """
    template["Parameters"].setdefault(
        "PolicyValidationMode",
        {
            "Type": "String",
            "Default": "IGNORE_ALL_FINDINGS",
            "AllowedValues": ["IGNORE_ALL_FINDINGS", "FAIL_ON_ANY_FINDINGS"],
            "Description": (
                "How strictly AgentCore validates the Cedar policies this stack creates. "
                "IGNORE_ALL_FINDINGS, the default, still gets you a default-deny engine whose "
                "policies name every permitted tool explicitly; it skips the advisory findings "
                "analysis, not the rejections that matter (a wildcard resource and a "
                "non-existent gateway are refused in both modes). FAIL_ON_ANY_FINDINGS turns "
                "any finding into a failed stack, including a finding about a Cedar statement "
                "you supplied yourself, which is why it is not the default. Both modes work: "
                "the role that creates the policies is granted bedrock-agentcore:InvokeGateway "
                "on this stack's own gateway, without which CreatePolicy fails in EITHER mode "
                "with 'Insufficient permissions to call gateway'. See README > Authorization "
                "for what that grant allows."
            ),
        },
    )


LAMBDA_VPC_CONDITION = "HasLambdaVpcConfig"


def _apply_lambda_vpc_config(template: dict) -> list[str]:
    """Let the recipient place this stack's Lambdas in their own VPC.

    Every emitted Lambda ran outside any VPC, on the AWS-managed network, with
    unrestricted egress to the internet. For most recipients that is fine. For a
    regulated one it is disqualifying: their controls require the function to sit in
    a private subnet behind their own security group so egress is least-privilege
    (ARCC cnt_dh50RmkA8h91jK: tightly restrict outbound traffic and justify each
    destination; cnt_h4bRcEdetHM9Jv: reach AWS services over VPC endpoints). There
    was no parameter to express it, so their only options were to fork the template
    or not deploy.

    Both parameters default to empty and the condition then resolves to
    ``AWS::NoValue``, so an existing stack is unchanged by this — a recipient who
    does not care sees no difference.

    Deliberately no emitted security group and no emitted subnets. A default group
    would have to allow egress to something, and anything permissive enough to work
    is exactly what the recipients who want this are trying to prevent; anything
    tight enough to satisfy them depends on their endpoint layout, which we cannot
    know. So the customer supplies both, and the README says what access the
    functions actually need.
    """
    template.setdefault("Conditions", {})[LAMBDA_VPC_CONDITION] = {
        "Fn::Not": [{"Fn::Equals": [{"Fn::Join": ["", {"Ref": "LambdaSubnetIds"}]}, ""]}]
    }
    touched = []
    for logical_id, resource in template.get("Resources", {}).items():
        if resource.get("Type") != "AWS::Lambda::Function":
            continue
        resource.setdefault("Properties", {})["VpcConfig"] = {
            "Fn::If": [
                LAMBDA_VPC_CONDITION,
                {
                    "SubnetIds": {"Ref": "LambdaSubnetIds"},
                    "SecurityGroupIds": {"Ref": "LambdaSecurityGroupIds"},
                },
                {"Ref": "AWS::NoValue"},
            ]
        }
        touched.append(logical_id)

    # A VPC-attached function creates an elastic network interface in the subnet,
    # and it is the *execution role* that must be allowed to, not the deploying
    # principal. AWSLambdaBasicExecutionRole does not grant it, so without this the
    # function would be created and then fail every invocation with
    # "The provided execution role does not have permissions to call
    # CreateNetworkInterface on EC2" — a runtime error, after a green stack.
    # AWS's own AWSLambdaVPCAccessExecutionRole is the documented grant and is a
    # superset of the basic one; it is attached only under the same condition so a
    # recipient who does not use a VPC gains no ec2 permissions at all.
    for resource in template.get("Resources", {}).values():
        if resource.get("Type") != "AWS::IAM::Role":
            continue
        statements = resource.get("Properties", {}).get("AssumeRolePolicyDocument", {}).get("Statement", [])
        if not any(s.get("Principal", {}).get("Service") == "lambda.amazonaws.com" for s in statements):
            continue
        managed = resource["Properties"].setdefault("ManagedPolicyArns", [])
        vpc_access = {
            "Fn::If": [
                LAMBDA_VPC_CONDITION,
                {"Fn::Sub": "arn:${AWS::Partition}:iam::aws:policy/service-role/AWSLambdaVPCAccessExecutionRole"},
                {"Ref": "AWS::NoValue"},
            ]
        }
        if vpc_access not in managed:
            managed.append(vpc_access)
    return sorted(touched)


def _apply_lambda_log_groups(template: dict) -> list[str]:
    """Give every Lambda in this stack an owned log group with a retention limit.

    Two defects, one fix. A Lambda with no log group resource creates
    ``/aws/lambda/<function>`` itself on first invocation, which means the group is
    not part of the stack: ``cloudformation delete-stack`` leaves it behind, and it
    keeps its logs for ever because CloudWatch Logs retains indefinitely by default
    (ARCC cnt_qf7wYkuSRSM5fl: set a retention limit via CloudFormation). Deploying and
    tearing down repeatedly therefore accumulates log groups nobody owns, holding
    whatever the agent's inputs contained, indefinitely.

    The group name is deliberately NOT the default ``/aws/lambda/<function>``. Adding
    a log group resource under the default name to a stack whose Lambda has already
    run fails the update with "already exists" — the group exists but belongs to
    nobody, so CloudFormation cannot adopt it. Naming it under the stack means the
    name has never existed before, so this is safe to apply to a stack already in
    service; ``LoggingConfig.LogGroup`` points the function at it. The roles authorize
    ``log-group:*`` in this account and region (see _log_group_resources), so no role
    change is needed.

    ``KmsKeyId`` is not set here either: ``AWS::Logs::LogGroup`` is in
    CUSTOMER_KEY_PROPERTIES, so ``_apply_customer_key`` sets it under the same
    opt-in condition as everything else. That pass has to run after this one.
    """
    touched = []
    for logical_id in [
        lid for lid, r in template.get("Resources", {}).items() if r.get("Type") == "AWS::Lambda::Function"
    ]:
        group_id = f"{logical_id}LogGroup"
        if group_id in template["Resources"]:
            continue
        template["Resources"][group_id] = {
            "Type": "AWS::Logs::LogGroup",
            # No DeletionPolicy here: AWS::Logs::LogGroup is in
            # DATA_BEARING_RESOURCE_TYPES, so _apply_data_retention stamps it with
            # whatever the recipient chose. This pass therefore has to run *before*
            # that one — see the call order in generate().
            "Properties": {
                "LogGroupName": {"Fn::Sub": f"/aws/lambda/${{AWS::StackName}}/{logical_id}"},
                "RetentionInDays": {"Ref": "LogRetentionInDays"},
            },
        }
        function = template["Resources"][logical_id]
        function.setdefault("Properties", {})["LoggingConfig"] = {"LogGroup": {"Ref": group_id}}
        depends = function.setdefault("DependsOn", [])
        if isinstance(depends, str):
            depends = [depends]
            function["DependsOn"] = depends
        if group_id not in depends:
            depends.append(group_id)
        touched.append(logical_id)
    return sorted(touched)


def _runtime_endpoint_qualifier(name: object, endpoint_id: str) -> str:
    """An endpoint's ``Name`` as text that can sit inside an outer ``Fn::Sub``.

    Flattened rather than nested on purpose: ``Fn::Sub``'s variable map accepts
    ``Ref`` and ``Fn::GetAtt`` but NOT another ``Fn::Sub``, and the inner string's
    ``${DeploymentName}`` resolves identically when it is inlined into the outer one.

    Anything else raises. The alternative — skipping a shape this cannot flatten —
    would silently leave that endpoint's log group with no retention and no key,
    which is the exact defect this whole pass exists to fix, and it would leave it
    with no failing test either.
    """
    if isinstance(name, str):
        return name
    if isinstance(name, dict) and isinstance(name.get("Fn::Sub"), str):
        return name["Fn::Sub"]
    raise ValueError(
        f"runtime endpoint {endpoint_id} has a Name this generator cannot turn into a log "
        f"group name ({name!r}); Custom::RuntimeLogGroup would leave its logs ungoverned"
    )


def _apply_runtime_log_groups(template: dict) -> list[str]:
    """Govern the log groups AgentCore creates for each runtime it is asked to run.

    ``AWS::BedrockAgentCore::Runtime`` has no logging properties whatsoever, so
    nothing in the emitted template reached these groups: the service created
    ``/aws/bedrock-agentcore/runtimes/<runtimeId>-<qualifier>`` itself, with no
    retention limit and the AWS-owned key, and a ``delete-stack`` left it behind. That
    is the agent's conversation — what it was asked and what it answered — kept for
    ever, unencrypted by the customer's key, in a group no stack owns. ARCC
    cnt_sSTfcrsdyTSviN item 6 requires customer content to have a retention period and
    item 8 requires customer-managed-key support so the customer controls it; ARCC
    cnt_qf7wYkuSRSM5fl requires the retention limit to be set through CloudFormation.
    The same two knobs already cover the Lambda groups (see _apply_lambda_log_groups);
    this is the resource that could not be declared.

    Declaring them as ``AWS::Logs::LogGroup`` is not an option, which is why this is a
    custom resource: the runtime creates the groups during the stack's own create, so a
    declared group of the same name collides with one that already exists and belongs
    to nobody. The handler creates-or-adopts instead, and never deletes.

    One resource per runtime, covering EVERY endpoint plus DEFAULT. The service makes a
    group per endpoint — proven live on a runtime with one named endpoint, which had
    both — and the named one is where an invoke against that qualifier writes. A pass
    that governed only ``-DEFAULT`` would have looked correct in the template and
    covered the empty group.
    """
    resources = template.get("Resources", {})
    added: list[str] = []
    for runtime_id in sorted(lid for lid, r in resources.items() if r.get("Type") == "AWS::BedrockAgentCore::Runtime"):
        qualifiers = ["DEFAULT"]
        endpoints: list[str] = []
        for endpoint_id, endpoint in sorted(resources.items()):
            if endpoint.get("Type") != "AWS::BedrockAgentCore::RuntimeEndpoint":
                continue
            runtime_ref = endpoint.get("Properties", {}).get("AgentRuntimeId")
            get_att = runtime_ref.get("Fn::GetAtt") if isinstance(runtime_ref, dict) else None
            if not get_att or get_att[0] != runtime_id:
                continue
            endpoints.append(endpoint_id)
            qualifiers.append(_runtime_endpoint_qualifier(endpoint["Properties"].get("Name"), endpoint_id))

        logical_id = f"{runtime_id}LogGroups"
        if logical_id in resources:
            continue
        resource = {
            "Type": "Custom::RuntimeLogGroup",
            "Properties": {
                "ServiceToken": {"Fn::GetAtt": ["CfnProviderLambda", "Arn"]},
                # A fresh dict per entry, never a shared one: two identical objects in
                # a template become a YAML anchor and an alias on dump, and
                # CloudFormation rejects the result outright. See _customer_key_ref.
                "LogGroupNames": [
                    {
                        "Fn::Sub": [
                            f"{RUNTIME_LOG_GROUP_PREFIX}/${{RuntimeId}}-{qualifier}",
                            {"RuntimeId": {"Fn::GetAtt": [runtime_id, "AgentRuntimeId"]}},
                        ]
                    }
                    for qualifier in qualifiers
                ],
                "RetentionInDays": {"Ref": "LogRetentionInDays"},
                # KmsKeyArn is NOT set here. Custom::RuntimeLogGroup is in
                # CUSTOMER_KEY_PROPERTIES, so _apply_customer_key adds it under the
                # same opt-in condition as every other encrypted resource. That pass
                # has to run after this one — see the call order in generate().
            },
        }
        if endpoints:
            # The GetAtt above already orders this after the runtime. The endpoints are
            # a separate matter: their groups do not exist until the endpoint does, and
            # nothing else in this resource references them.
            resource["DependsOn"] = endpoints
        template["Resources"][logical_id] = resource
        added.append(logical_id)
    return added


def _gateway_invoke_permission(function_logical_id: str) -> dict:
    """Let the AgentCore Gateway invoke *function_logical_id*, and nobody else's.

    Checkov CKV_AWS_364 on the emitted template: all three of these permissions
    named the ``bedrock-agentcore.amazonaws.com`` service principal with neither
    ``SourceAccount`` nor ``SourceArn``. A service-principal grant with no source
    constraint is the textbook confused deputy — it authorizes AgentCore acting for
    *any* AWS account, so somebody else's gateway configured against this function's
    ARN would be allowed to invoke it. The KB tool Lambda holds ``bedrock:Retrieve``
    on this account's knowledge base, so that is a read path into it.

    ``SourceAccount`` and not ``SourceArn``: the gateway ARN would be the tighter
    constraint, but the AgentCore resource types publish no ``Arn`` attribute this
    generator has verified, and cfn-lint ships no schema for them to catch a wrong
    ``Fn::GetAtt``. Account scoping is what can be asserted, and it closes the
    cross-account path, which is the actual threat.

    One helper for all three call sites rather than three identical dicts, so a
    fourth Lambda target cannot be added without the constraint.
    """
    return {
        "Type": "AWS::Lambda::Permission",
        "Properties": {
            "FunctionName": {"Fn::GetAtt": [function_logical_id, "Arn"]},
            "Action": "lambda:InvokeFunction",
            "Principal": "bedrock-agentcore.amazonaws.com",
            "SourceAccount": {"Ref": "AWS::AccountId"},
        },
    }


class CfnExportUnsupportedError(Exception):
    """The canvas is valid but this exporter cannot represent it faithfully.

    Distinct from a bug: the deploy would succeed on the live Step Functions
    path, and refusing is the correct answer only because emitting a template
    anyway would emit the *wrong* stack. Callers should surface the message to
    the user as a 4xx — it is written to be actionable, not internal.
    """


# ---------------------------------------------------------------------------
# Source-code integrity
# ---------------------------------------------------------------------------

# The empty digest, i.e. content_digest({}). A parameter default of "" would let a
# deploy that skipped deploy.sh silently opt out of verification, so the default is
# always a real digest and the handler treats "" as "no digest given".
EMPTY_CONTENT_DIGEST = "sha256:e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"


def content_digest(files: dict[str, str]) -> str:
    """Reproducible digest over a set of named source files.

    Hashes the file *contents*, not an archive of them: deploy.sh builds the zip
    with ``zip -r``, which embeds mtimes, so two zips of identical code differ
    while this value does not.

    The algorithm is duplicated in two other places on purpose — the generated
    deploy.sh recomputes it in bash from the local files, and the cfn-provider
    Lambda recomputes it in Python from the uploaded zip. All three must agree, so
    keep it boringly simple: one ``<name>  <sha256>`` line per file, sorted by
    name, hashed.
    """
    lines = "".join(f"{name}  {hashlib.sha256(body.encode()).hexdigest()}\n" for name, body in sorted(files.items()))
    return "sha256:" + hashlib.sha256(lines.encode()).hexdigest()


# ---------------------------------------------------------------------------
# Knowledge Base vector store
# ---------------------------------------------------------------------------

# Must match knowledge_base_step._build_storage_config's default. A mismatch does
# not fail the deploy — it creates an index the KB never queries, so retrieval
# silently returns nothing.
DEFAULT_VECTOR_INDEX_NAME = "bedrock-knowledge-base-default-index"

# AWS::S3Vectors::Index requires an explicit Dimension, and it MUST equal the
# embedding model's output width or ingestion fails at the first vector write.
# The live path hardcodes 1024 because it only ever ran Titan v2; a template the
# customer edits is more likely to see another model, so map the ones Bedrock
# offers for knowledge bases.
EMBEDDING_MODEL_DIMENSIONS: dict[str, int] = {
    "amazon.titan-embed-text-v1": 1536,
    "amazon.titan-embed-text-v2:0": 1024,  # configurable 256/512/1024; 1024 is the default
    "amazon.titan-embed-image-v1": 1024,
    "cohere.embed-english-v3": 1024,
    "cohere.embed-multilingual-v3": 1024,
}
DEFAULT_EMBEDDING_DIMENSION = 1024


def _embedding_dimension(embedding_model_id: str) -> int:
    """Vector width for *embedding_model_id*, defaulting to 1024."""
    return EMBEDDING_MODEL_DIMENSIONS.get(embedding_model_id, DEFAULT_EMBEDDING_DIMENSION)


def _s3_vectors_is_stack_managed(kb_config: dict) -> bool:
    """True when the exported stack must create the vector bucket and index itself.

    The live Step Functions path calls s3vectors:CreateVectorBucket/CreateIndex
    before CreateKnowledgeBase (see knowledge_base_step, lessons Bug 145 —
    Bedrock does NOT auto-provision an S3 Vectors store, and a missing one
    surfaces as the misleading "unable to assume the given role"). A template has
    no imperative step, so it declares the two resources instead.
    """
    if kb_config.get("vectorStoreType", "s3_vectors") != "s3_vectors":
        return False
    return not kb_config.get("s3VectorsIndexArn") and not kb_config.get("s3VectorsBucketArn")


# ---------------------------------------------------------------------------
# LiteLLM gateway provider
# ---------------------------------------------------------------------------

# A Secrets Manager secret ARN. Secrets Manager appends a 6-character random
# suffix to the name, and both the suffixed and unsuffixed forms are accepted by
# the API, so the tail is deliberately loose.
SECRETSMANAGER_ARN_PATTERN = r"^arn:aws[a-zA-Z-]*:secretsmanager:[a-z0-9-]+:\d{12}:secret:.+$"

# https only. The virtual key rides this connection on every MCP call, so a
# template that could be pointed at http:// by overriding a parameter would let
# anyone who can run a stack update downgrade the transport. The AllowedPattern
# on LiteLLMGatewayUrl enforces the same thing at deploy time.
LITELLM_URL_PATTERN = r"^https://[^\s]+$"


def _litellm_export_settings(gateway_config: dict | None) -> dict:
    """What the exported stack needs in order to talk to a customer's LiteLLM proxy.

    Reads both spellings of every key: the canvas sends camelCase and the stored
    form is snake_case (``resolve_gateway_provider`` carries the same pairs for
    the same reason).

    The virtual key itself is deliberately NOT in the result. ARCC guidance on
    customer-provided secrets (``cnt_77BHvX7WzuG1X8``) is explicit that a service
    must never ask a customer to supply a credential through CloudFormation and
    must accept a Secrets Manager ARN instead, so an inline ``litellm_api_key``
    left on the canvas is dropped here rather than written into the export. A
    template is a file people commit to git, paste into tickets and forward to
    colleagues; a key in it is a key that has leaked.
    """
    cfg = gateway_config or {}
    base_url = str(cfg.get("litellm_base_url") or cfg.get("litellmBaseUrl") or "").strip()
    if not base_url:
        raise CfnExportUnsupportedError(
            "This agent's gateway uses the LiteLLM provider but names no proxy base "
            "URL, so there is nothing to point the exported stack at. Set the LiteLLM "
            "base URL on the gateway node and export again."
        )
    # Scheme check only. The live path additionally resolves the hostname and
    # rejects private/IMDS addresses, because it actually connects to the proxy
    # from the control plane; the export only writes the URL into a document. A
    # private base URL is legitimate here — the customer may deploy this stack
    # inside the VPC that can reach it — so refusing it would be wrong.
    if not re.match(LITELLM_URL_PATTERN, base_url):
        raise CfnExportUnsupportedError(
            f"The LiteLLM base URL {base_url!r} is not https. The exported runtime "
            "sends your virtual key to this URL on every request, so only https is "
            "accepted. Fix the base URL on the gateway node and export again."
        )

    servers = cfg.get("litellm_servers") or cfg.get("litellmServers") or []
    if isinstance(servers, str):
        servers = [s.strip() for s in servers.split(",") if s.strip()]
    servers = [str(s).strip() for s in servers if str(s).strip()]

    # An ARN from an earlier live deploy of the same canvas becomes the parameter
    # default, so a customer who deployed through the platform first does not have
    # to re-enter it. Absent, the parameter has no default and CloudFormation
    # requires a value — which is the correct failure: this stack cannot work
    # without a key, and a placeholder default would produce a stack that deploys
    # and then 401s on every tool call.
    secret_arn = str(cfg.get("litellm_api_key_ref") or cfg.get("litellmApiKeyRef") or "").strip()
    if secret_arn and not re.match(SECRETSMANAGER_ARN_PATTERN, secret_arn):
        # Not fatal: drop it and let the operator supply one. Baking an
        # unrecognized string in as a default would fail the deploy on a pattern
        # mismatch with no hint of where the value came from.
        logger.warning("Ignoring a stored LiteLLM key reference that is not a Secrets Manager ARN")
        secret_arn = ""

    return {
        "base_url": base_url,
        "mcp_url": resolve_mcp_url(base_url, servers),
        "servers": servers,
        "secret_arn": secret_arn,
    }


